// Get latest status from flow context
const dellStatus = flow.get('status_dell_t310_status') || null;
const hpStatus = flow.get('status_hp_dl360p_status') || null;
const mediaStatus = flow.get('status_media_server_status') || null;

let statusText = '📊 *Server Status*\n\n';

if (dellStatus) {
    const state = dellStatus.server_state || 'unknown';
    const emoji = state === 'online' ? '🟢' : (state === 'offline' ? '🔴' : '🟡');
    const timestamp = dellStatus.timestamp ? new Date(dellStatus.timestamp).toLocaleString() : 'N/A';
    statusText += `${emoji} *Dell T310*: ${state.toUpperCase()}\n`;
    statusText += `   Last update: ${timestamp}\n\n`;
} else {
    statusText += '🟡 *Dell T310*: No data\n\n';
}

if (hpStatus) {
    const state = hpStatus.server_state || 'unknown';
    const emoji = state === 'online' ? '🟢' : (state === 'offline' ? '🔴' : '🟡');
    const timestamp = hpStatus.timestamp ? new Date(hpStatus.timestamp).toLocaleString() : 'N/A';
    statusText += `${emoji} *HP DL360p*: ${state.toUpperCase()}\n`;
    statusText += `   Last update: ${timestamp}\n\n`;
} else {
    statusText += '🟡 *HP DL360p*: No data\n\n';
}

if (mediaStatus) {
    const state = mediaStatus.server_state || 'unknown';
    const emoji = state === 'online' ? '🟢' : (state === 'offline' ? '🔴' : '🟡');
    const timestamp = mediaStatus.timestamp ? new Date(mediaStatus.timestamp).toLocaleString() : 'N/A';
    const uptime = mediaStatus.uptime ? `\n   Uptime: ${mediaStatus.uptime}` : '';
    statusText += `${emoji} *Media Server*: ${state.toUpperCase()}${uptime}\n`;
    statusText += `   Last update: ${timestamp}\n`;
} else {
    statusText += '🟡 *Media Server*: No data\n';
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: statusText,
    parse_mode: 'Markdown'
};
msg.topic = 'send';

return msg;

// Store status in flow context
flow.set('status_dell_t310_status', msg.payload);

// Check if state changed and notify Telegram
const metadataKey = 'status_metadata_dell_t310_status';
let metadata = flow.get(metadataKey) || {
    currentState: 'Unknown',
    lastChangedMs: null
};

const newState = msg.payload.server_state || 'unknown';

if (newState !== metadata.currentState) {
    // State changed - notify Telegram
    const chatIds = flow.get('telegram_chat_ids') || [];
    if (chatIds.length === 0) {
        // Update metadata even if no chats registered
        metadata.currentState = newState;
        metadata.lastChangedMs = Date.now();
        flow.set(metadataKey, metadata);
        return null;
    }

    const stateEmoji = newState === 'online' ? '🟢' : (newState === 'offline' ? '🔴' : '🟡');

    const notificationText = `${stateEmoji} *Dell T310 Status Changed*\n\n` +
        `State: *${newState.toUpperCase()}*\n` +
        `Previous: ${metadata.currentState}\n` +
        `Time: ${new Date().toLocaleString()}`;

    // Update metadata
    metadata.currentState = newState;
    metadata.lastChangedMs = Date.now();
    flow.set(metadataKey, metadata);

    // Return array of messages (Node-RED will send each as separate message)
    return chatIds.map(chatId => ({
        payload: {
            chatId: chatId,
            type: 'message',
            content: notificationText,
            parse_mode: 'Markdown'
        }
    }));
}

return null;

