return null;

// Only notify for telegram-initiated commands
const requestId = msg.payload.request_id || '';
if (!requestId.startsWith('telegram-')) {
    return null; // Not a telegram command
}

const chatIds = flow.get('telegram_chat_ids') || [];
if (chatIds.length === 0) {
    return null;
}

// Extract server name from topic (dell/t310, hp/dl360p, media/server)
const topicParts = msg.topic.split('/');
let serverName = topicParts.slice(0, 2).join('/').toUpperCase();
if (topicParts[0] === 'media') serverName = 'Media Server';
else if (topicParts[0] === 'dell') serverName = 'Dell T310';
else if (topicParts[0] === 'hp') serverName = 'HP DL360p';

const ok = msg.payload.success === true;
const statusEmoji = ok ? '✅' : '❌';
const message = msg.payload.message || 'Command executed';

let responseText = `${statusEmoji} *Command Response*\n\n`;
responseText += `Server: *${serverName}*\n`;
responseText += `Status: ${ok ? 'SUCCESS' : 'FAILED'}\n`;
responseText += `Message: ${message}\n`;

if (msg.payload.request_id) {
    responseText += `\nRequest ID: \`${msg.payload.request_id}\``;
}

return chatIds.map(chatId => ({
    payload: {
        chatId: chatId,
        type: 'message',
        content: responseText,
        parse_mode: 'Markdown'
    }
}));

